export class Order {
  @PrimaryColumn({ name: 'id', type: 'bigint' })
  id!: string

  @Column({ name: 'status', type: 'varchar', length: 20 })
  status!: OrderStatus

  @Column({ name: 'couponCode', type: 'varchar', length: 255, nullable: true })
